// Copyright 2016-2021 Crytek GmbH / Crytek Group. All rights reserved.#include "StdAfx.h"#include "ToneMapping.h"#include "ColorGrading.h"#include "Bloom.h"#include "SunShafts.h"#include "DepthOfField.h"#include "D3DPostProcess.h"#include "SceneReferredExport.h"#include <Common/RenderDisplayContext.h>// Mechanical light loss of the field-dependent pupil, packed for HDRVignetteParams// (.y = barrel offset per unit field height, .z = barrel radius, .w = diagnostic flag).//// This is the ONE place the loss is applied: the pupil is clipped by the barrel whether or not// a pixel is in focus, so it belongs to the whole picture and not just to the blurred parts.// The gather only reshapes its kernel and the splat divides its deposit back out, precisely so// that this term is not counted a second time.//// The values are read straight off the post effect params rather than through// CDepthOfField::GetParams(), which advances the time-of-day focus smoother on every call and// must stay at one call per frame (see the warning in DepthOfField.h).static Vec4 ResolveVignetteParams(){	const float fAmount = clamp_tpl(CRenderer::CV_r_HDRVignetteAmount, 0.0f, 4.0f);	CPostEffectsMgr* pPostMgr = PostEffectMgr();	if (!pPostMgr)		return Vec4(fAmount, 0.0f, 1.0f, 0.0f);	CEffectParam* pCatEye = pPostMgr->GetByName("Dof_User_CatEye");	CEffectParam* pPupilScale = pPostMgr->GetByName("Dof_User_PupilScale");	if (!pCatEye || !pPupilScale)		return Vec4(fAmount, 0.0f, 1.0f, 0.0f);	// Only the barrel geometry matters here: coma and astigmatism redistribute light inside the	// pupil, they do not block any of it.	const Vec4 vFieldPupil = CDepthOfFieldStage::ResolveFieldPupil(pCatEye->GetParam(), pPupilScale->GetParam(), 0.0f, 0.0f);	return Vec4(fAmount, vFieldPupil.x, vFieldPupil.y, (CRenderer::CV_r_DofFieldDebug > 0) ? 1.0f : 0.0f);}// The EV100 at which CE's ComputeExposure() returns exactly 1.0://     exposure = (LIGHT_UNIT_SCALE / 1.2) * 2^-EV100 == 1  <=>  EV100 = log2(LIGHT_UNIT_SCALE / 1.2)// = log2(10000 / 1.2) = 13.0245867. Used to pin the tone map to unit exposure on the// scene-referred path, where the exposure has already been applied to the scene data// (SceneReferredSpec.md D3/D6, decisions/s1-exposure-constant.md).static const float kSceneReferredUnityEV = 13.0245867f;// ---------------------------------------------------------------------------// S8 - the ATMOSPHERIC CONDITION on the screen-space sun shafts// (decisions/s8-sun-shafts-condition.md approach A, research/s8-sun-shafts-condition.md).//// A crepuscular ray is not a property of a bright sun. It is single scattering along the view// ray, L = INTEGRAL sigma_s * p(theta) * E_perp * V dx, and every one of those four factors can// be zero. CE's screen-space effect implements none of them: p(theta) is approximated by the// radial falloff around the sun's screen position, E_perp was restored by S2, V is a// brightness-and-depth heuristic - and sigma_s, the one that decides whether the phenomenon// EXISTS, is simply absent. So the stock effect paints rays on a bone-dry cloudless day at// whatever RaysAmount the level authored, which is the user's round-3 observation.//// Clear air to fog is a factor of 50-1000 in sigma_s; a 100 m beam in clear air is about 4 % of// the sky it is drawn against, which is below the threshold at which anyone sees structure in a// soft gradient. That is the whole dynamic range of the effect, and there was no term carrying// any of it.//// The proxy: the fog system's own scattering coefficient at the camera, which is already on the// render thread in per-metre units. Both SRenderViewShaderConstants members hold// log2(e) * sigma at the viewer's height (D3DHWShader.cpp sGetVolumetricFogParams and// sGetVolumetricFogHeightDensityParams, both of which apply the editor's x 0.01), and both are// published UNCONDITIONALLY by the TOD - so this needs no new constant, no new plumbing and no// dependency on whether volumetric fog is actually rendering. e_VolumetricFog only selects WHICH// of the two systems is the one in force.//// The condition is the optical depth over a reference beam, saturating://     cond = 1 - exp(-sigma_s * L_ref)// L_ref is the one invented number here and is labelled as one: no engine anywhere gives a// screen-space shaft a physical formulation to borrow a value from. See// r_ShaftAtmosphereRefLength and SceneReferredCalibration.md 3.//// Where this proxy is WRONG, on the record: it is the density AT THE CAMERA, not along the beam// (a camera above a ground-fog layer reads as clear), local fog volumes never reach the global// parameters, and there is still no occluder test. The hybrid with volumetric fog's real froxel// shafts (approach C) has none of those problems and is the destination; this scalar is the part// of it that can be had for one multiply.// ---------------------------------------------------------------------------struct SShaftAtmosphereCondition{	float sigmaS       = 0.0f;   //!< scattering coefficient at the camera, per metre	float visibilityKm = 0.0f;   //!< Koschmieder visual range 3.912 / sigma_e, km	float condition    = 1.0f;   //!< the multiplier applied to the shaft composite	bool  bActive      = false;  //!< false = the shafts were left at the authored amount};static SShaftAtmosphereCondition ResolveShaftAtmosphereCondition(const CRenderView* pRenderView){	SShaftAtmosphereCondition result;	if (CRenderer::CV_r_ShaftAtmosphereCondition == 0 || pRenderView == nullptr)		return result;	const SRenderViewShaderConstants& PF = pRenderView->GetShaderConstants();	// Which fog system is the one describing this scene's air. e_VolumetricFog is	// VF_REQUIRE_APP_RESTART, so this cannot change under us mid-session.	ICVar* pVolFogVar = gEnv->pConsole ? gEnv->pConsole->GetCVar("e_VolumetricFog") : nullptr;	const bool bVolFog = (pVolFogVar != nullptr && pVolFogVar->GetIVal() != 0);	// Both are log2(e) * sigma; divide the log2(e) back out exactly as the shaders do	// (VolumeLighting.cfi). The result is extinction, per metre, at the viewer's height.	const float kInvLog2e = 1.0f / 1.44269502f;	const float sigmaE = max(0.0f, (bVolFog ? PF.pVolumetricFogHeightDensityParams.y	                                        : PF.pVolumetricFogParams.y) * kInvLog2e);	// Scattering is nearly all of extinction for water droplets and most aerosols (single-scatter	// albedo 0.85-1.0); soot is the exception and CE has no parameter for it. VOLFOG2_INSCATTER is	// the only albedo-shaped knob the engine exposes, default 1.0, so it doubles as the albedo for	// both fog systems - which at every stock preset is a multiply by one. Clamped to [0,1]	// because an albedo above 1 is not a thing, whatever the slider allows.	const float albedo = clamp_tpl(PF.pVolumetricFogScatteringParams.x, 0.0f, 1.0f);	result.sigmaS = sigmaE * albedo;	// Koschmieder, for the debug readout only - it is a property of extinction, not of scattering,	// so it is computed from sigmaE before the albedo.	result.visibilityKm = (sigmaE > 1e-9f) ? (3.912f / sigmaE) * 0.001f : 1e6f;	const float refLength = max(0.0f, CRenderer::CV_r_ShaftAtmosphereRefLength);	result.condition = 1.0f - expf(-result.sigmaS * refLength);	result.bActive = true;	return result;}// ---------------------------------------------------------------------------// The camera stage's white balance (SceneReferredSpec.md S5).//// WB is the CAMERA'S SETTING, not a description of the scene: the scene is lit at whatever it is// lit at, and the camera is told what to call white. So the transform is a chromatic adaptation// FROM the temperature the camera is set to TOWARDS the neutral setting - which is why 3200 K in// daylight comes out blue and 8000 K comes out warm, exactly as a stills camera does.//// The neutral is 6500 K + tint 0 evaluated through THIS SAME locus, not a tabulated D65. That// makes the neutral setting an exact identity by construction (source white == destination white// -> the adaptation is the identity matrix to the last bit) instead of an identity to six// decimals, which is what "6500 = no-op" has to mean if the switch is to be provable.//// CCT -> xy is Kim et al.'s cubic fit to the Planckian locus (1667..25000 K), the formula// Resolve, Nuke and every camera pipeline use. Tint is a Duv offset perpendicular to the locus// in the CIE 1960 UCS, the space Duv is defined in; positive tint is magenta (below the locus),// negative is green, matching the sign convention of every grading tool.// ---------------------------------------------------------------------------namespace{//! AP1 (ACEScg primaries) -> CIE XYZ with the ACES D60 white. Verified against PyOpenColorIO//! 2.5 by tools/ocio-bake/verify_matrices.py; the same numbers CommonMath.cfi carries.static const Matrix33 kAP1ToXYZ(	0.66245418f, 0.13400421f, 0.15618769f,	0.27222872f, 0.67408177f, 0.05368952f,	-0.00557465f, 0.00406073f, 1.01033910f);//! Bradford cone response, the chromatic adaptation transform D5 names.static const Matrix33 kBradford(	0.8951f, 0.2664f, -0.1614f,	-0.7502f, 1.7135f, 0.0367f,	0.0389f, -0.0685f, 1.0296f);//! Kim et al. (2002) cubic fit to the Planckian locus.static Vec2 CCTToXY(float kelvin){	const float T = clamp_tpl(kelvin, 1667.0f, 25000.0f);	const float invT = 1.0f / T;	const float invT2 = invT * invT;	const float invT3 = invT2 * invT;	const float x = (T <= 4000.0f)		? (-0.2661239e9f * invT3 - 0.2343589e6f * invT2 + 0.8776956e3f * invT + 0.179910f)		: (-3.0258469e9f * invT3 + 2.1070379e6f * invT2 + 0.2226347e3f * invT + 0.240390f);	const float x2 = x * x;	const float x3 = x2 * x;	float y;	if (T <= 2222.0f)		y = -1.1063814f * x3 - 1.34811020f * x2 + 2.18555832f * x - 0.20219683f;	else if (T <= 4000.0f)		y = -0.9549476f * x3 - 1.37418593f * x2 + 2.09137015f * x - 0.16748867f;	else		y = 3.0817580f * x3 - 5.87338670f * x2 + 3.75112997f * x - 0.37001483f;	return Vec2(x, y);}static Vec2 XYToUV1960(const Vec2& xy){	const float d = -2.0f * xy.x + 12.0f * xy.y + 3.0f;	return Vec2(4.0f * xy.x / d, 6.0f * xy.y / d);}static Vec2 UV1960ToXY(const Vec2& uv){	const float d = 2.0f * uv.x - 8.0f * uv.y + 4.0f;	return Vec2(3.0f * uv.x / d, 2.0f * uv.y / d);}//! The white point for a (Kelvin, tint) camera setting, as XYZ normalised to Y = 1.//! tint is -1..1; full scale is a Duv of 0.03, which is far past anything a shoot uses and//! still short of leaving the region the locus fit is valid in.static Vec3 CameraWhiteXYZ(float kelvin, float tint){	Vec2 xy = CCTToXY(kelvin);	if (fabsf(tint) > 1e-6f)	{		// The normal to the locus, taken from a finite difference along it. Duv is signed		// positive ABOVE the locus (green); the tint control is signed positive toward magenta,		// hence the minus.		const Vec2 uv0 = XYToUV1960(CCTToXY(kelvin * 0.999f));		const Vec2 uv1 = XYToUV1960(CCTToXY(kelvin * 1.001f));		Vec2 tangent(uv1.x - uv0.x, uv1.y - uv0.y);		const float len = sqrtf(tangent.x * tangent.x + tangent.y * tangent.y);		if (len > 1e-9f)		{			tangent.x /= len;			tangent.y /= len;			const Vec2 normal(-tangent.y, tangent.x);			Vec2 uv = XYToUV1960(xy);			uv.x += normal.x * (-0.03f * tint);			uv.y += normal.y * (-0.03f * tint);			xy = UV1960ToXY(uv);		}	}	const float y = max(xy.y, 1e-6f);	return Vec3(xy.x / y, 1.0f, (1.0f - xy.x - xy.y) / y);}//! The Bradford adaptation from white src to white dst, expressed in the working space (AP1).//! Returns the identity when the two whites coincide, which is what makes the neutral setting a//! true no-op rather than a near-one.static Matrix33 ResolveWhiteBalanceMatrix(float kelvin, float tint, bool bEnabled){	Matrix33 identity;	identity.SetIdentity();	if (!bEnabled)		return identity;	const Vec3 src = CameraWhiteXYZ(kelvin, tint);	const Vec3 dst = CameraWhiteXYZ(6500.0f, 0.0f);	if (src.IsEquivalent(dst, 1e-9f))		return identity;	const Vec3 coneSrc = kBradford * src;	const Vec3 coneDst = kBradford * dst;	Matrix33 scale;	scale.SetIdentity();	scale.m00 = coneDst.x / max(coneSrc.x, 1e-9f);	scale.m11 = coneDst.y / max(coneSrc.y, 1e-9f);	scale.m22 = coneDst.z / max(coneSrc.z, 1e-9f);	const Matrix33 catXYZ = kBradford.GetInverted() * scale * kBradford;	// XYZ in, XYZ out; the shader multiplies AP1 values, so the adaptation is conjugated by the	// primaries matrix. AP1 (1,1,1) is preserved exactly at the neutral setting because the	// adaptation itself is the identity there, whatever the primaries.	return kAP1ToXYZ.GetInverted() * catXYZ * kAP1ToXYZ;}} // namespacevoid CToneMappingStage::Execute(){	FUNCTION_PROFILER_RENDERER();	PROFILE_LABEL_SCOPE("TONEMAPPING");	CSunShaftsStage* pSunShaftsStage = m_graphicsPipeline.GetStage<CSunShaftsStage>();	CBloomStage* pBloomStage = m_graphicsPipeline.GetStage<CBloomStage>();	CColorGradingStage* pColorGradingStage = m_graphicsPipeline.GetStage<CColorGradingStage>();	bool bColorGradingEnabled = pColorGradingStage->IsStageActive(EShaderRenderingFlags(0));	bool bSunShaftsEnabled = pSunShaftsStage->IsStageActive(EShaderRenderingFlags(0));	bool bBloomEnabled = pBloomStage->IsStageActive(EShaderRenderingFlags(0));	bool bApplyDithering = CRenderer::CV_r_HDRDithering && CRenderer::CV_r_PostProcess;	// (r_HDRVignetting used to gate the dead SAMPLE2 flag below and has no reader left; the	// vignette strength travels in HDRVignetteParams.x, from r_HDRVignetteAmount.)	// D14 (SceneReferredSpec.md): the scene-referred path takes its exposure from the cinematic	// camera and must do so whatever r_HDREyeAdaptationMode says. The engine default is 2, the	// legacy Krawczyk path, which reads hdrSetupParams[4] and silently ignores every EV the	// camera writes - the sample project only works today because its .cryproject happens to set	// 1. Rather than have the plugin write that global VF_DUMPTODISK cvar (ClearSavedBaselines()	// would drop the latch on entering game mode and it would never be restored), the stage grows	// a third branch and the cvar keeps its full meaning for the stock path.	//	// FOR S0 THIS BRANCH IS DELIBERATELY IDENTICAL TO MODE 1: the same EV-based exposure out of	// hdrSetupParams[3], the same shader permutation. Nothing about the picture changes yet -	// this item only decides WHERE the exposure comes from, so that S1 has exactly one place to	// replace with the camera's pre-exposure and nothing else has to move.	// Three gates, not one, because the bisection cvar r_SceneReferredStage has to be able to	// stop between them (r_SceneReferredStage documentation in RendererCVars.cpp):	//   bSceneReferred      - stage 3. THE HDRFinalPass permutation bit (SAMPLE0). It selects the	//                         additive pre-curve sun-shaft composite (S2) AND the body of the	//                         output transform (S4) in one flag, because the shader ties them; it	//                         is therefore raised at the earlier of the two stages and the LUTs	//                         below simply report size 0 until stage 5.	//   bSceneReferredExp   - stage 2. The pre-exposure is already in the data, so the tone map	//                         must apply none of its own (S1).	//   bSceneReferredLook  - stage 5. The ODT and look LUTs and the colour-chart skip (S4/S5/D9).	const bool bSceneReferred = CRendererResources::IsSceneReferredStage(3);	const bool bSceneReferredExp = CRendererResources::IsSceneReferredStage(2);	const bool bSceneReferredLook = CRendererResources::IsSceneReferredStage(5);	// S6's export tap. The exporter hands back a ring slot to write this frame into, or nullptr	// when nothing is armed - which is every frame in normal use, and the whole feature then costs	// one branch. Only the GRADED tap changes this pass: it is an extra SV_Target1 write under	// %_RT_SAMPLE2. The negative tap is a blit of $HDRTarget after the pass and needs no	// permutation at all.	CSceneReferredExport& exporter = CSceneReferredExport::Get();	CTexture* pExportTex = CRendererResources::IsSceneReferredStage(6)		? exporter.BeginFrame(m_graphicsPipeline,		                      m_graphicsPipelineResources.m_pTexHDRTarget->GetWidth(),		                      m_graphicsPipelineResources.m_pTexHDRTarget->GetHeight())		: nullptr;	const bool bExportGraded = pExportTex && exporter.WantsGradedTap();	// The display chain's two LUTs. ccam parsed the .cube files and uploaded the 3D textures; all	// that arrives here is a texture ID, resolved the same way the colour grading stage resolves	// its identity chart. A size of 0 means the slot is empty - a legitimate answer for the look	// (D10) and a visible mistake for the output transform (D13), and the shader treats them so.	CTexture* pLmtTex = CRendererResources::s_ptexWhite3D;	CTexture* pOdtTex = CRendererResources::s_ptexWhite3D;	float fLmtSize = 0.0f;	float fOdtSize = 0.0f;	if (bSceneReferredLook)	{		if (CPostEffectsMgr* pPostMgr = PostEffectMgr())		{			const auto resolveLut = [](CEffectParam* pId, CEffectParam* pSize, CTexture*& pTex, float& fSize)			{				if (!pId || !pSize)					return;				const int nId = (int)pId->GetParam();				const float size = pSize->GetParam();				// Both have to be there. A texture that went away under a still-published ID is				// the one case that would sample garbage rather than nothing.				if (nId <= 0 || size < 2.0f)					return;				CTexture* pCandidate = CTexture::GetByID(nId);				if (!CTexture::IsTextureExist(pCandidate))					return;				pTex = pCandidate;				fSize = size;			};			resolveLut(pPostMgr->GetLutLMTParam(), pPostMgr->GetLutLMTSizeParam(), pLmtTex, fLmtSize);			resolveLut(pPostMgr->GetLutODTParam(), pPostMgr->GetLutODTSizeParam(), pOdtTex, fOdtSize);		}	}	CShader* pShader = CShaderMan::s_shHDRPostProcess;	CTexture* pSunShaftsTex = CRendererResources::s_ptexBlack;	CTexture* pColorChartTex = CRendererResources::s_ptexBlack;	if (bSunShaftsEnabled)		pSunShaftsTex = pSunShaftsStage->GetFinalOutputRT();	if (bColorGradingEnabled)	{		if (CTexture* pColorChartTexTentative = pColorGradingStage->GetColorChart())			pColorChartTex = pColorChartTexTentative;		else			bColorGradingEnabled = false;	}	// Bit 13: the scene-referred branch. It has to be in the mask or the pass is not marked dirty	// when the switch flips and the old permutation keeps running (r_HDRDebug occupies bits 9-12).	int featureMask = ((int)bSunShaftsEnabled << 1) | ((int)bColorGradingEnabled << 2) | ((int)bBloomEnabled << 3) |	                  ((CRenderer::CV_r_HDREyeAdaptationMode & 0xF) << 5) | ((CRenderer::CV_r_HDRDebug & 0xF) << 9) |	                  ((int)bSceneReferred << 13) | ((int)bExportGraded << 14) |	                  ((int)bSceneReferredExp << 15) | ((int)bSceneReferredLook << 16);	if (m_passToneMapping.IsDirty(featureMask, pSunShaftsTex->GetTextureID(), pColorChartTex->GetTextureID(), CRendererResources::s_ptexCurLumTexture->GetTextureID(),	                              pLmtTex->GetTextureID(), pOdtTex->GetTextureID(),	                              bExportGraded ? pExportTex->GetTextureID() : 0))	{		uint64 rtMask = 0;		if (bSceneReferred)		{			// Scene-referred exposure. S0: the EV path, so SAMPLE4 stays clear exactly as it does			// in mode 1 and the shader keeps using ComputeExposure(). S1 replaces this branch.			//			// S2 claims SAMPLE0 as THE scene-referred permutation of HDRFinalPass. It selects the			// additive, pre-curve sun-shaft composite instead of the stock post-saturate headroom			// blend (decisions/s2-sun-shafts.md approach A) and it is the same bit S4's output			// transform will branch the body of FilmMapping on, which is why it is spent here and			// not on the exposure - S1 pinned that with a constant precisely so this bit stayed			// free. One extra permutation of one fullscreen pass.			rtMask |= g_HWSR_MaskBit[HWSR_SAMPLE0];		}		else if (!bSceneReferredExp && CRenderer::CV_r_HDREyeAdaptationMode == 2)		{			// !bSceneReferredExp as well: between stages 2 and 3 the exposure constant below is			// already pinned to unity, and the Krawczyk branch reads .y/.z as min and max			// EXPOSURE rather than as an EV window - a silently wrong picture. Below stage 2			// nothing has moved and this is the stock test.			rtMask |= g_HWSR_MaskBit[HWSR_SAMPLE4];		}		// D9: the colour chart is part of the stock LDR stage and is skipped whole under the		// switch. Not setting the flag rather than binding an identity chart - the fetch and the		// lerp go away with it, and the chart pipeline keeps running so that turning ccam off		// restores the stock look without a rebuild.		if (bColorGradingEnabled && !bSceneReferredLook)			rtMask |= g_HWSR_MaskBit[HWSR_SAMPLE1];		// SAMPLE2 used to be set here for vignetting and was read NOWHERE: the gate was inverted		// at some point and the strength constant (HDRVignetteParams.x) replaced it entirely.		// It cost a permutation axis of this pass for nothing. Removing it invalidates every		// cached HDRFinalPass variant, the stock ones included - which S4 does anyway - and		// changes no pixel on either path.		if (bBloomEnabled)			rtMask |= g_HWSR_MaskBit[HWSR_SAMPLE3];		if (bSunShaftsEnabled)			rtMask |= g_HWSR_MaskBit[HWSR_SAMPLE5];		if (bApplyDithering)			rtMask |= g_HWSR_MaskBit[HWSR_SAMPLE6];		// SAMPLE2 is the S6 export permutation - the bit S4 freed when it removed the dead		// vignette gate. With it clear the shader declares one output and this pass binds one		// render target, exactly as it did before S6 existed.		if (bExportGraded)			rtMask |= g_HWSR_MaskBit[HWSR_SAMPLE2];		// TODO: CPostEffectContext::GetDstBackBufferTexture() pre-EnableAltBackBuffer()		static CCryNameTSCRC techToneMapping("HDRFinalPass");		m_passToneMapping.SetTechnique(pShader, techToneMapping, rtMask);		m_passToneMapping.SetRenderTarget(0, m_graphicsPipelineResources.m_pTexDisplayTargetDst);		// Slot 1 is the pre-ODT value, bound ONLY while a graded capture is armed: both because		// MaxRendertargetCount is 4 and one of them is not free to spend permanently, and because		// an unbound SV_Target1 with the permutation still set is the silent failure the		// featureMask bit above exists to prevent.		m_passToneMapping.SetRenderTarget(1, bExportGraded ? pExportTex : nullptr);		m_passToneMapping.SetState(GS_NODEPTHTEST);		m_passToneMapping.SetFlags(CPrimitiveRenderPass::ePassFlags_RequireVrProjectionConstants);		m_passToneMapping.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants);	// Enables reflection constants addition in the shader		CTexture* pBloomTex = bBloomEnabled ? m_graphicsPipelineResources.m_pTexHDRFinalBloom : CRendererResources::s_ptexBlack;		m_passToneMapping.SetSampler(0, EDefaultSamplerStates::LinearClamp);		m_passToneMapping.SetTexture(0, m_graphicsPipelineResources.m_pTexHDRTarget);		m_passToneMapping.SetTexture(1, CRendererResources::s_ptexCurLumTexture);		m_passToneMapping.SetTexture(2, pBloomTex);		m_passToneMapping.SetTexture(7, CRendererResources::s_ptexVignettingMap);		m_passToneMapping.SetTexture(8, pColorChartTex);		m_passToneMapping.SetTexture(9, pSunShaftsTex);		// The display chain's LUTs. Bound unconditionally, because the branch inside the shader		// is dynamic (a constant compare, not a permutation) and an unbound Texture3D would be a		// hole in the resource set even on the frames the sample is skipped. White3D is the		// harmless stand-in: 1x1x1, and never sampled while the size constant says 0.		//		// s1 is a NEW sampler slot. s0's LinearClamp already clamps on all three axes - every		// default sampler state sets address W explicitly - so this is the same state on its own		// slot rather than a new state; the 2D fetches keep s0 and the LUT keeps s1, which means		// neither can be changed by accident for the other's sake.		m_passToneMapping.SetTexture(3, pLmtTex);		m_passToneMapping.SetTexture(4, pOdtTex);		m_passToneMapping.SetSampler(1, EDefaultSamplerStates::LinearClamp);		m_passToneMapping.SetRequireWorldPos(true);		m_passToneMapping.SetRequirePerViewConstantBuffer(true);	}	static CCryNameR eyeAdaptationName("HDREyeAdaptation");	static CCryNameR vignetteParamsName("HDRVignetteParams");	static CCryNameR filmCurveName("HDRFilmCurve");	static CCryNameR colorBalanceName("HDRColorBalance");	static CCryN